Item.method_code:
const {
	itemType,
	itemTypeName,
	location
} = options;
const labelTemplate = target.labelTemplate || target.label;
const itemTypeLabel = itemType.label || itemTypeName;
const label = labelTemplate.replace('{ItemType}', itemTypeLabel);
const openNewCommand = options.commandFactory('OpenNewItem', { itemType, itemTypeName, location });
const disabled = !openNewCommand.canExecute();

return {
	disabled,
	label,
	labelTemplate
};
